#!/usr/bin/env node
/*
 * bundle.js — fold the terminal app and the engine it requires into one file.
 *
 * Why hand-roll this instead of using a bundler: the whole project's rule is no
 * dependencies and no build step, and the module graph here is six files with
 * literal relative requires. A map from that literal string to a wrapped
 * function is the entire problem. The output is a single .js that runs on any
 * Node 18+, and it is also what a Node SEA build needs, since a sealed
 * executable has no filesystem beside it to require() from.
 *
 *   node packaging/bundle.js [outfile]
 */
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const ENTRY = './jedi-cli.js';
// Order is irrelevant — the shim resolves lazily — but keep it readable.
const MODULES = ['./js/version.js', './js/data.js', './js/syslogger.js', './js/jedi.js', './forward.js', ENTRY];

const { VERSION } = require('../js/version.js');
const out = process.argv[2] || path.join(ROOT, 'dist', `jedi-${VERSION}.js`);

let body = `#!/usr/bin/env node
/* APEX JediSyslogger ${VERSION} — single-file terminal build.
 * Generated by packaging/bundle.js from the same sources the web app loads.
 * Do not edit: change js/*.js or jedi-cli.js and rebuild. */
'use strict';
(function () {
  const __mods = {};
  const __cache = {};
  // Only the literal specifiers the sources actually use are resolvable; a
  // require() of anything else falls through to the real one, which is how
  // Node's own core modules (fs, net, dgram, https, readline) keep working.
  const __require = (id) => {
    const key = id.replace(/^\\.\\//, './');
    if (!(key in __mods)) return require(id);
    if (__cache[key]) return __cache[key].exports;
    const m = { exports: {} };
    __cache[key] = m;
    __mods[key](m, m.exports, __require, key);
    return m.exports;
  };
`;

for (const id of MODULES) {
  const src = fs.readFileSync(path.join(ROOT, id), 'utf8')
    .replace(/^#!.*\n/, '')                       // a shebang is only valid on line 1
    .replace(/^﻿/, '');
  body += `\n  __mods[${JSON.stringify(id)}] = function (module, exports, require, __filename) {\n${src}\n  };\n`;
}

// The engine modules attach to globalThis.JS and jedi-cli requires them by the
// same paths the browser loads, so nothing above needed rewriting.
body += `\n  __require(${JSON.stringify(ENTRY)});\n})();\n`;

fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, body);
fs.chmodSync(out, 0o755);
process.stderr.write(`bundled ${MODULES.length} modules → ${path.relative(ROOT, out)} (${(body.length / 1024).toFixed(0)} KB)\n`);
